import ast, hashlib, pathlib, sys

bad = []
for f, (h, text) in FILES.items():
    ast.parse(text)
    p = pathlib.Path(f)
    if p.exists() and p.read_text() == text:
        continue
    if h is None:
        if p.exists():
            bad.append(f)
        continue
    if not p.exists() or hashlib.sha256(p.read_bytes()).hexdigest() != h:
        bad.append(f)
if bad:
    sys.exit(f"⚠️ {bad} が版105b の形ではない（手で直した所があるか、版が違う）。何も書き換えていない")
for f, (_, text) in FILES.items():
    pathlib.Path(f).write_text(text)
print("✅ 版107 を当てた。次に python3 check_v107.py", flush=True)
